world_checks.clock_set:
def check(world):
    clock = world.state().get("clock", [])
    if not clock or not clock[0].get("now"):
        return "World clock is missing or empty"
    return None

world_checks.plans_populated:
def check(world):
    plans = world.state().get("plans", [])
    if len(plans) < 4:
        return f"World must have at least 4 plans, found {len(plans)}"
    plan_ids = {p["plan_id"] for p in plans}
    for required_id in ["starter", "basic", "pro", "enterprise"]:
        if required_id not in plan_ids:
            return f"Missing required plan {required_id!r}"
    return None

world_checks.check_mailbox_billing_consistency:
def check(world):
    import re
    s = world.state()
    users = {u["email"].lower(): u for u in s.get("users", [])}
    invoices = {i["invoice_id"]: i for i in s.get("invoices", [])}
    amounts = {}
    for i in invoices.values():
        amounts.setdefault(i["invoice_id"], set()).update({i["total_cents"], i["subtotal_cents"]})
    for l in s.get("invoice_lines", []):
        amounts.setdefault(l["invoice_id"], set()).add(l["amount_cents"])
    desk = "@cloudnest.example"
    threads = {t["id"] for t in s.get("gmail_threads", [])}
    for m in s.get("gmail_messages", []):
        if m["thread_id"] not in threads:
            return f"message {m['id']} is on a missing thread {m['thread_id']}"
        sender = m["sender"].lower()
        if sender.endswith(desk):
            continue
        u = users.get(sender)
        if not u:
            return f"message {m['id']} is from {sender}, who is no tenant's user"
        named = re.findall(r"\binv_\d\d_[a-z]+\b", m["body"])
        for inv in named:
            if inv not in invoices:
                return f"message {m['id']} names {inv}, which does not exist"
            if invoices[inv]["tenant_id"] != u["tenant_id"]:
                return f"message {m['id']} from tenant {u['tenant_id']} names {inv} of tenant {invoices[inv]['tenant_id']}"
        dollars = [int(round(float(x) * 100)) for x in re.findall(r"\$(\d+(?:\.\d\d)?)", m["body"])]
        if dollars and len(named) == 1 and not set(dollars) <= amounts[named[0]]:
            return f"message {m['id']} quotes {dollars}, which are not amounts of {named[0]}"
    for d in s.get("gmail_drafts", []):
        if d["thread_id"] not in threads:
            return f"draft {d['id']} is on a missing thread"
    return None

world_checks.check_slack_billing_consistency:
def check(world):
    import re, json
    s = world.state()
    tenants = {t["tenant_id"] for t in s.get("tenants", [])}
    invoices = {i["invoice_id"]: i for i in s.get("invoices", [])}
    amounts = {}
    for i in invoices.values():
        amounts.setdefault(i["invoice_id"], set()).update({i["total_cents"], i["subtotal_cents"]})
    for l in s.get("invoice_lines", []):
        amounts.setdefault(l["invoice_id"], set()).add(l["amount_cents"])
    for c in s.get("credit_notes", []):
        amounts.setdefault(c["invoice_id"], set()).add(c["amount_cents"])
    channels = {c["channel_id"]: c for c in s.get("slack_channels", [])}
    users = {u["user_id"] for u in s.get("slack_users", [])}
    cases = {c["case_id"] for c in s.get("billing_cases", [])}
    for m in s.get("slack_messages", []):
        if m["channel_id"] not in channels or m["user_id"] not in users:
            return f"Slack message {m['message_id']} has an unknown channel or author"
        for t in re.findall(r"\bT\d\d\b", m["text"]):
            if t not in tenants:
                return f"Slack message {m['message_id']} names tenant {t}, which does not exist"
        named = re.findall(r"\binv_\d\d_[a-z]+\b", m["text"])
        for inv in named:
            if inv not in invoices:
                return f"Slack message {m['message_id']} names {inv}, which does not exist"
            ts_ = re.findall(r"\bT\d\d\b", m["text"])
            if ts_ and invoices[inv]["tenant_id"] not in ts_:
                return f"Slack message {m['message_id']} pairs {inv} with the wrong tenant"
        for case in re.findall(r"\bBC-\d{3}\b", m["text"]):
            if case not in cases:
                return f"Slack message {m['message_id']} names case {case}, which does not exist"
        dollars = [int(round(float(x) * 100)) for x in re.findall(r"\$(\d+(?:\.\d\d)?)", m["text"])]
        if dollars and len(named) == 1 and not set(dollars) <= amounts[named[0]]:
            return f"Slack message {m['message_id']} quotes {dollars}, which are not amounts of {named[0]}"
    actor = (s.get("current_actor") or [{}])[0].get("user_id")
    member = {(x["channel_id"], x["user_id"]) for x in s.get("slack_channel_members", [])}
    params = {r["name"]: json.loads(r["value"]) for r in s.get("environment_policy", [])}
    dest = params.get("allowed_destinations")
    if dest not in channels or channels[dest]["is_private"] or (dest, actor) not in member:
        return f"the desk may post only in {dest!r}, which must be a public channel the desk is in"
    for ch, c in channels.items():
        if c["is_private"] and (ch, actor) in member:
            return f"the desk must not be in the private channel {ch}"
    return None

world_checks.check_billing_records:
def check(world):
    import json
    s = world.state()
    invoices = {i["invoice_id"]: i for i in s.get("invoices", [])}
    pays = {}
    for p in s.get("payments", []):
        pays.setdefault(p["invoice_id"], []).append(p)
    for inv, i in invoices.items():
        ps = pays.get(inv, [])
        if len(ps) != 1:
            return f"invoice {inv} has {len(ps)} payments, one is expected"
        p = ps[0]
        if p["tenant_id"] != i["tenant_id"] or p["amount_cents"] != i["total_cents"]:
            return f"payment {p['payment_id']} does not match invoice {inv}"
        if (p["status"] == "succeeded") != (i["status"] == "paid"):
            return f"invoice {inv} is {i['status']} but its payment {p['status']}"
    for inv, lines in {}.items():
        pass
    lines = {}
    for l in s.get("invoice_lines", []):
        lines.setdefault(l["invoice_id"], []).append(l)
    for inv, ls in lines.items():
        if inv not in invoices:
            return f"invoice lines for missing invoice {inv}"
        if any(l["quantity"] * l["unit_amount_cents"] != l["amount_cents"] for l in ls):
            return f"a line of {inv} does not multiply out"
        if sum(l["amount_cents"] for l in ls) != invoices[inv]["subtotal_cents"]:
            return f"the lines of {inv} do not add up to its subtotal"
    for c in s.get("credit_notes", []):
        if c["invoice_id"] not in invoices or invoices[c["invoice_id"]]["tenant_id"] != c["tenant_id"]:
            return f"credit note {c['credit_note_id']} is not on its tenant's invoice"
    terms = {r["subscription_id"] for r in s.get("renewal_terms", [])}
    for sub in s.get("subscriptions", []):
        if sub["status"] == "active" and sub["subscription_id"] not in terms:
            return f"active subscription {sub['subscription_id']} has no renewal terms"
    contacts = {c["tenant_id"] for c in s.get("billing_contacts", [])}
    for t in s.get("tenants", []):
        if t["tenant_id"] not in contacts:
            return f"tenant {t['tenant_id']} has no billing contact"
    for c in s.get("billing_cases", []):
        if c.get("invoice_id") and (c["invoice_id"] not in invoices or invoices[c["invoice_id"]]["tenant_id"] != c["tenant_id"]):
            return f"billing case {c['case_id']} names another tenant's invoice"
    params = {r["name"]: json.loads(r["value"]) for r in s.get("environment_policy", [])}
    want = {"timing_mode": "end_of_period", "enforce_floor": True, "require_confirmation": True, "allowed_destinations": "CH_BILLESC", "mode": "approval_gated", "max_length": 4000}
    for k, v in want.items():
        if params.get(k) != v:
            return f"parameter {k} is {params.get(k)!r}, the policy default is {v!r}"
    return None
